using Dm;

internal static class Program
{
    const BindingFlags Flags = BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic;
    static readonly List<object> Results = [];
    static readonly List<(string Kind, string Name)> Owned = [];
    static readonly string Prefix = "I09_" + Guid.NewGuid().ToString("N")[..16].ToUpperInvariant();
    static string Raw = "";
    static int Main(string[] args)
    {
        if (args.Length > 0 && args[0] == "audit")
        {
            try
            {
                Raw = Environment.GetEnvironmentVariable("DAMENG_TEST_CONNECTION_STRING") ?? throw new InvalidOperationException("integration_pending");
                using var audit = Open();
                Console.WriteLine(JsonSerializer.Serialize(new { identity = "WDM_PROVIDER_TEST", remaining_i09w_objects = Scalar(audit, "SELECT COUNT(*) FROM USER_OBJECTS WHERE OBJECT_NAME LIKE 'I09W_%'") }));
                return 0;
            }
            catch(Exception error) { Console.WriteLine(JsonSerializer.Serialize(new { audit_failure=Error(error) })); return 1; }
        }
        bool clean = false;
        bool fatal = false;
        try
        {
            Raw = Environment.GetEnvironmentVariable("DAMENG_TEST_CONNECTION_STRING") ?? throw new InvalidOperationException("integration_pending");
            using (var c = Open())
            {
                Results.Add(new { kind = "identity", user = "WDM_PROVIDER_TEST", server = c.ServerVersion, assembly = typeof(DmConnection).Assembly.FullName });
                Create(c, "PROCEDURE", "P", "(A IN INT, B OUT INT, C IN OUT INT) AS BEGIN B := A + 10; C := C + A; END;");
                Create(c, "FUNCTION", "F", "(A IN INT, B IN INT) RETURN INT AS BEGIN RETURN A * 100 + B; END;");
                Create(c, "PROCEDURE", "Z", "AS BEGIN NULL; END;");
                Create(c, "PROCEDURE", "R", "(B OUT INT) AS BEGIN B := 77; SELECT 11 AS N FROM DUAL UNION ALL SELECT 12 FROM DUAL; SELECT 21 AS N FROM DUAL; END;");
                Create(c, "PROCEDURE", "T", "(D OUT DECIMAL(28,9), T OUT TIMESTAMP(7), Z OUT DATETIME(7) WITH TIME ZONE, B OUT BLOB, C OUT CLOB) AS BEGIN D := 1234567890123456789.123456789; T := CAST('2026-10-15 12:34:56.1234567' AS TIMESTAMP(7)); Z := CAST('2026-10-15 12:34:56.1234567 +05:30' AS DATETIME(7) WITH TIME ZONE); B := HEXTORAW('0011FEFF'); C := 'I09 中文 CLOB'; END;");
                foreach(int scale in new[]{7,9})Create(c,"PROCEDURE","Q"+scale,$"(I IN TIMESTAMP({scale}), O OUT TIMESTAMP({scale}), S OUT VARCHAR(100), J IN DATETIME({scale}) WITH TIME ZONE, Z OUT DATETIME({scale}) WITH TIME ZONE, R OUT VARCHAR(100)) AS BEGIN O := I; S := TO_CHAR(O,'YYYY-MM-DD HH24:MI:SS.FF9'); Z := J; R := TO_CHAR(Z,'YYYY-MM-DD HH24:MI:SS.FF9 TZH:TZM'); END;");
                Create(c, "PROCEDURE", "L", "(A OUT SYS_REFCURSOR, B OUT SYS_REFCURSOR) AS BEGIN OPEN A FOR SELECT LEVEL AS N FROM DUAL CONNECT BY LEVEL<=20000; OPEN B FOR SELECT LEVEL+100000 AS N FROM DUAL CONNECT BY LEVEL<=20000; END;");
                Create(c,"TABLE","TEMP","(ID INT PRIMARY KEY, T TIMESTAMP(9), Z DATETIME(9) WITH TIME ZONE)");
                using(var insert=(DmCommand)c.CreateCommand()){insert.CommandText=$"INSERT INTO \"{Name("TEMP")}\" VALUES(1,:T,:Z)";var t=P("T",DmDbType.DateTime,ParameterDirection.Input,new DateTime(2026,10,15,12,34,56).AddTicks(1234567));t.DbType=DbType.DateTime2;t.Precision=9;var z=P("Z",DmDbType.DateTimeOffset,ParameterDirection.Input,new DateTimeOffset(2026,10,15,12,34,56,TimeSpan.FromMinutes(330)).AddTicks(1234567));z.Precision=9;insert.Parameters.Add(t);insert.Parameters.Add(z);insert.ExecuteNonQuery();}
                Create(c,"PROCEDURE","V",$"(O OUT TIMESTAMP(9), S OUT VARCHAR(100), Z OUT DATETIME(9) WITH TIME ZONE, R OUT VARCHAR(100)) AS BEGIN SELECT T, Z INTO O, Z FROM \"{Name("TEMP")}\" WHERE ID=1; S := TO_CHAR(O,'YYYY-MM-DD HH24:MI:SS.FF9'); R := TO_CHAR(Z,'YYYY-MM-DD HH24:MI:SS.FF9 TZH:TZM'); END;");
                Create(c, "TABLE", "BIZ", "(ID INT PRIMARY KEY)");
                Create(c, "PROCEDURE", "TX", $"(M IN INT, K IN INT) AS BEGIN INSERT INTO \"{Name("BIZ")}\" VALUES(K); IF M=1 THEN COMMIT; ELSIF M=2 THEN ROLLBACK; ELSIF M=3 THEN RAISE_APPLICATION_ERROR(-20009,'I09 controlled error'); END IF; END;");
                Create(c,"PROCEDURE","MORE","(D OUT DATE,T OUT TIME(6),I OUT INTERVAL DAY(2) TO SECOND(6),Y OUT INTERVAL YEAR(4) TO MONTH,S OUT VARCHAR(32),B OUT VARBINARY(4),X OUT DECIMAL(38,5)) AS BEGIN D:=DATE '2026-10-15';T:=TIME '12:34:56.123456';I:=INTERVAL '2 03:04:05.123456' DAY(2) TO SECOND(6);Y:=INTERVAL '3-4' YEAR(4) TO MONTH;S:='I09 字符串';B:=HEXTORAW('0011FEFF');X:=123456789012345678901234567890123.12345;END;");
                Create(c, "PROCEDURE", "E", "(B OUT INT) AS BEGIN B := 88; RAISE_APPLICATION_ERROR(-20009, 'I09 controlled error'); END;");
                Create(c, "PROCEDURE", "C", "(A OUT SYS_REFCURSOR, B OUT SYS_REFCURSOR, N OUT INT) AS BEGIN N := 99; OPEN A FOR SELECT 31 AS N FROM DUAL UNION ALL SELECT 32 FROM DUAL; OPEN B FOR SELECT 41 AS N FROM DUAL UNION ALL SELECT 42 FROM DUAL; END;");
            }
            Case("table_temporal_output",c=>{using var cmd=Proc(c,"V");foreach(var x in new[]{("O",DmDbType.DateTime),("S",DmDbType.VarChar),("Z",DmDbType.DateTimeOffset),("R",DmDbType.VarChar)})cmd.Parameters.Add(P(x.Item1,x.Item2,ParameterDirection.Output,DBNull.Value));cmd.Prepare();var meta=Metadata(cmd);var stmt=Statement(cmd)!;using var reader=cmd.ExecuteReader();return new{meta,wire=Wire(stmt),parameters=Values(cmd)};});
            foreach(int scale in new[]{7,9})Case("typed_temporal_echo_"+scale,c=>{using var cmd=Proc(c,"Q"+scale);DateTime value=new DateTime(2026,10,15,12,34,56).AddTicks(1234567);cmd.Parameters.Add(P("I",DmDbType.DateTime,ParameterDirection.Input,value));cmd.Parameters.Add(P("O",DmDbType.DateTime,ParameterDirection.Output,DBNull.Value));cmd.Parameters.Add(P("S",DmDbType.VarChar,ParameterDirection.Output,DBNull.Value));cmd.Parameters.Add(P("J",DmDbType.DateTimeOffset,ParameterDirection.Input,new DateTimeOffset(value,TimeSpan.FromMinutes(330))));cmd.Parameters.Add(P("Z",DmDbType.DateTimeOffset,ParameterDirection.Output,DBNull.Value));cmd.Parameters.Add(P("R",DmDbType.VarChar,ParameterDirection.Output,DBNull.Value));cmd.Parameters[0].DbType=DbType.DateTime2;cmd.Parameters[0].Precision=(byte)scale;cmd.Parameters[3].Precision=(byte)scale;cmd.Prepare();var meta=Metadata(cmd);var stmt=Statement(cmd)!;using var reader=cmd.ExecuteReader();return new{meta,wire=Wire(stmt),parameters=Values(cmd)};});
            foreach(int mode in new[]{0,1,2,3})Case("internal_transaction_"+mode,c=>{object? error=null;object? rollbackError=null;using(var tx=c.BeginTransaction()){using var cmd=Proc(c,"TX");cmd.Transaction=tx;cmd.Parameters.Add(P("M",DmDbType.Int32,ParameterDirection.Input,mode));cmd.Parameters.Add(P("K",DmDbType.Int32,ParameterDirection.Input,100+mode));try{cmd.ExecuteNonQuery();}catch(Exception e){error=Error(e);}try{tx.Rollback();}catch(Exception e){rollbackError=Error(e);}}using var fresh=Open();return new{error,rollbackError,rows=Scalar(fresh,$"SELECT COUNT(*) FROM \"{Name("BIZ")}\" WHERE ID={100+mode}")};});
            Case("async_scalar",c=>{using var cmd=Proc(c,"P");cmd.Parameters.Add(P("A",DmDbType.Int32,ParameterDirection.Input,2));cmd.Parameters.Add(P("B",DmDbType.Int32,ParameterDirection.Output,-1));cmd.Parameters.Add(P("C",DmDbType.Int32,ParameterDirection.InputOutput,5));var count=cmd.ExecuteNonQueryAsync().GetAwaiter().GetResult();return new{count,parameters=Values(cmd)};});
            Case("independent_cursors_remote_fetch",c=>{using var cmd=Proc(c,"L");cmd.Parameters.Add(P("A",DmDbType.RefCursor,ParameterDirection.Output,DBNull.Value));cmd.Parameters.Add(P("B",DmDbType.RefCursor,ParameterDirection.Output,DBNull.Value));using var a=cmd.ExecuteReader();using var b=IndependentReader((DmParameter)cmd.Parameters[1]);long sa=0,sb=0;int count=0;while(a.Read()){if(!b.Read())throw new InvalidOperationException("cursor_b_short");sa+=a.GetInt32(0);sb+=b.GetInt32(0);count++;}return new{count,sa,sb,b_extra=b.Read()};});
            Case("additional_types",c=>{using var cmd=Proc(c,"MORE");foreach(var x in new[]{("D",DmDbType.Date),("T",DmDbType.Time),("I",DmDbType.IntervalDayToSecond),("Y",DmDbType.IntervalYearToMonth),("S",DmDbType.VarChar),("B",DmDbType.VarBinary),("X",DmDbType.XDEC)})cmd.Parameters.Add(P(x.Item1,x.Item2,ParameterDirection.Output,DBNull.Value));cmd.Prepare();var meta=Metadata(cmd);var st=Statement(cmd)!;using var r=cmd.ExecuteReader();return new{meta,wire=Wire(st),parameters=Values(cmd)};});
            Case("types",c=>{using var cmd=Proc(c,"T");foreach(var item in new[]{("D",DmDbType.Decimal),("T",DmDbType.DateTime),("Z",DmDbType.DateTimeOffset),("B",DmDbType.Blob),("C",DmDbType.Clob)})cmd.Parameters.Add(P(item.Item1,item.Item2,ParameterDirection.Output,DBNull.Value));cmd.Prepare();var meta=Metadata(cmd);cmd.ExecuteNonQuery();return new{meta,parameters=Values(cmd)};});
            Case("controlled_error",c=>{using var cmd=Proc(c,"E");cmd.Parameters.Add(P("B",DmDbType.Int32,ParameterDirection.Output,-1));object? error=null;try{cmd.ExecuteNonQuery();}catch(Exception e){error=Error(e);}return new{error,parameters=Values(cmd)};});
            Case("mixed_cursor_and_regular_result",c=>{try{Create(c,"PROCEDURE","M","(A OUT SYS_REFCURSOR) AS BEGIN OPEN A FOR SELECT 31 AS N FROM DUAL; SELECT 11 AS N FROM DUAL; END;");using var cmd=Proc(c,"M");cmd.Parameters.Add(P("A",DmDbType.RefCursor,ParameterDirection.Output,DBNull.Value));using var r=cmd.ExecuteReader();return new{created=true,rows=ReadAll(r)};}catch(Exception e){return new{created=false,error=Error(e)};}});
            foreach(string pattern in new[]{"lower","colon","unknown"})Case("names_"+pattern,c=>{using var cmd=Proc(c,"P");foreach(var name in new[]{"C","B","A"})cmd.Parameters.Add(P(pattern=="lower"?name.ToLowerInvariant():pattern=="colon"?":"+name:"X"+name,DmDbType.Int32,name=="A"?ParameterDirection.Input:name=="B"?ParameterDirection.Output:ParameterDirection.InputOutput,name=="A"?2:name=="C"?5:-1));cmd.ExecuteNonQuery();return Values(cmd);});
            Case("quoted_no_parameters_call",c=>{using var cmd=(DmCommand)c.CreateCommand();cmd.CommandText=$"CALL \"WDM_PROVIDER_TEST\".\"{Name("Z")}\"()";return new{sql=cmd.CommandText,count=cmd.ExecuteNonQuery()};});
            Case("quoted_parameters",c=>{using var cmd=Proc(c,"P");cmd.CommandText=$"\"WDM_PROVIDER_TEST\".\"{Name("P")}\"";cmd.Parameters.Add(P("A",DmDbType.Int32,ParameterDirection.Input,2));cmd.Parameters.Add(P("B",DmDbType.Int32,ParameterDirection.Output,-1));cmd.Parameters.Add(P("C",DmDbType.Int32,ParameterDirection.InputOutput,5));cmd.Prepare();var sql=StatementSql(cmd);cmd.ExecuteNonQuery();return new{sql,parameters=Values(cmd)};});
            foreach(string kind in new[]{"scalar","null","cursor","types"})Case("wire_"+kind,c=>{using var cmd=Proc(c,kind=="cursor"?"C":kind=="types"?"T":"P");if(kind=="types"){foreach(var item in new[]{("D",DmDbType.Decimal),("T",DmDbType.DateTime),("Z",DmDbType.DateTimeOffset),("B",DmDbType.Blob),("C",DmDbType.Clob)})cmd.Parameters.Add(P(item.Item1,item.Item2,ParameterDirection.Output,DBNull.Value));}else if(kind=="cursor"){cmd.Parameters.Add(P("A",DmDbType.RefCursor,ParameterDirection.Output,DBNull.Value));cmd.Parameters.Add(P("B",DmDbType.RefCursor,ParameterDirection.Output,DBNull.Value));cmd.Parameters.Add(P("N",DmDbType.Int32,ParameterDirection.Output,-1));}else{cmd.Parameters.Add(P("A",DmDbType.Int32,ParameterDirection.Input,kind=="null"?DBNull.Value:2));cmd.Parameters.Add(P("B",DmDbType.Int32,ParameterDirection.Output,-1));cmd.Parameters.Add(P("C",DmDbType.Int32,ParameterDirection.InputOutput,kind=="null"?DBNull.Value:5));}cmd.Prepare();var st=Statement(cmd)!;using var reader=cmd.ExecuteReader();return new{wire=Wire(st),connection=ConnectionMetadata(c)};});
            foreach (string order in new[]{"ABC","CBA"}) Case("scalar_" + order, c => { using var cmd = Proc(c,"P"); foreach(char name in order) cmd.Parameters.Add(P(name.ToString(), DmDbType.Int32, name == 'A' ? ParameterDirection.Input : name == 'B' ? ParameterDirection.Output : ParameterDirection.InputOutput, name == 'A' ? 2 : name == 'C' ? 5 : -1)); cmd.Prepare(); var meta=Metadata(cmd); var preparedSql=StatementSql(cmd); var count=cmd.ExecuteNonQuery(); return new { meta, count, parameters=Values(cmd), preparedSql, sql=StatementSql(cmd) }; });
            foreach (int position in new[]{0,1,2}) Case("return_" + position,c=>{ using var cmd=Proc(c,"F"); var p=new List<DmParameter>{P("A",DmDbType.Int32,ParameterDirection.Input,3),P("B",DmDbType.Int32,ParameterDirection.Input,4)};p.Insert(position,P("RETURN_VALUE",DmDbType.Int32,ParameterDirection.ReturnValue,-1));foreach(var x in p)cmd.Parameters.Add(x); cmd.Prepare();var meta=Metadata(cmd);var preparedSql=StatementSql(cmd);var count=cmd.ExecuteNonQuery(); return new{meta,count,parameters=Values(cmd),preparedSql,sql=StatementSql(cmd)};});
            Case("no_parameters",c=>{using var cmd=Proc(c,"Z");cmd.Prepare();var sql=StatementSql(cmd);return new{count=cmd.ExecuteNonQuery(),sql};});
            Case("null",c=>{using var cmd=Proc(c,"P");cmd.Parameters.Add(P("A",DmDbType.Int32,ParameterDirection.Input,DBNull.Value));cmd.Parameters.Add(P("B",DmDbType.Int32,ParameterDirection.Output,-1));cmd.Parameters.Add(P("C",DmDbType.Int32,ParameterDirection.InputOutput,DBNull.Value));cmd.ExecuteNonQuery();return Values(cmd);});
            foreach(bool early in new[]{false,true}) Case("ordinary_results_early_"+early,c=>{using var cmd=Proc(c,"R");cmd.Parameters.Add(P("B",DmDbType.Int32,ParameterDirection.Output,-1));using var r=cmd.ExecuteReader();var before=Values(cmd); var rows=early ? new List<object>() : ReadAll(r); r.Close();return new{before,rows,after=Values(cmd),r.RecordsAffected};});
            Case("independent_cursor_statement",c=>{using var cmd=Proc(c,"C");cmd.Parameters.Add(P("A",DmDbType.RefCursor,ParameterDirection.Output,DBNull.Value));cmd.Parameters.Add(P("B",DmDbType.RefCursor,ParameterDirection.Output,DBNull.Value));cmd.Parameters.Add(P("N",DmDbType.Int32,ParameterDirection.Output,-1));cmd.Prepare();var before=CursorMetadata(cmd);using var parent=cmd.ExecuteReader();var after=CursorMetadata(cmd);var parameter=(DmParameter)cmd.Parameters[1];var statement=parameter.GetType().GetField("m_refCursorStmt",Flags)!.GetValue(parameter)!;var fields=statement.GetType().GetFields(Flags);var cache=fields.Single(f=>f.FieldType.Name=="DmResultSetCache").GetValue(statement);var info=fields.First(f=>f.FieldType.Name=="DmInfo").GetValue(statement);var ctor=typeof(DmDataReader).GetConstructors(Flags).Single(x=>x.GetParameters().Length==3&&x.GetParameters()[0].ParameterType.Name=="DmResultSetCache");using var child=(DbDataReader)ctor.Invoke(new[]{cache,info,(object)CommandBehavior.Default});var rows=new List<object>();for(int i=0;i<2;i++){rows.Add(new{cursor="B",read=child.Read(),value=child.GetValue(0)});rows.Add(new{cursor="A",read=parent.Read(),value=parent.GetValue(0)});}return new{before,after,rows};});
            foreach(string end in new[]{"complete","parent_close","transaction_commit","connection_close"}) Case("cursors_"+end,c=>{ using var tx=end=="transaction_commit"?c.BeginTransaction():null;using var cmd=Proc(c,"C");cmd.Transaction=tx;cmd.Parameters.Add(P("A",DmDbType.RefCursor,ParameterDirection.Output,DBNull.Value));cmd.Parameters.Add(P("B",DmDbType.RefCursor,ParameterDirection.Output,DBNull.Value));cmd.Parameters.Add(P("N",DmDbType.Int32,ParameterDirection.Output,-1));cmd.Prepare();var meta=Metadata(cmd);using var r=cmd.ExecuteReader();var before=Values(cmd);var rows=new List<object>();if(end=="complete")rows=ReadAll(r);else {rows.Add(new{first=r.Read(),value=r.GetValue(0)});if(end=="parent_close")r.Close();if(end=="transaction_commit")tx!.Commit();if(end=="connection_close")c.Close();try{rows.Add(new{read_after_end=r.Read()});}catch(Exception e){rows.Add(Error(e));}}return new{meta,before,rows,after=Values(cmd)};});
        }
        catch(Exception e){fatal=true;Results.Add(new{fatal=Error(e)});}
        finally
        {
            try { using(var c=Open())foreach(var item in Owned.AsEnumerable().Reverse())if(Exists(c,item.Name))Exec(c,$"DROP {item.Kind} \"{item.Name}\"");using var fresh=Open();clean=Owned.All(x=>!Exists(fresh,x.Name));Results.Add(new{cleanup_verified=clean,owned=Owned.Select(x=>new{x.Kind,x.Name})}); }
            catch(Exception e){Results.Add(new{cleanup_failure=Error(e)});}
        }
        string json=JsonSerializer.Serialize(Results,new JsonSerializerOptions{WriteIndented=true});
        if(args.Length>0)File.WriteAllText(args[0],json+"\n");else Console.WriteLine(json);
        return clean && !fatal?0:1;
    }
    static DmConnection Open(){var c=new DmConnection(Raw);try{c.Open();if(Convert.ToString(Scalar(c,"SELECT USER FROM DUAL"))?.Trim()!="WDM_PROVIDER_TEST"||Convert.ToString(Scalar(c,"SELECT SF_GET_SCHEMA_NAME_BY_ID(CURRENT_SCHID()) FROM DUAL"))?.Trim()!="WDM_PROVIDER_TEST")throw new InvalidOperationException("identity_rejected");return c;}catch{c.Dispose();throw;}}
    static string Name(string suffix)=>Prefix+"_"+suffix;
    static void Create(DmConnection c,string kind,string suffix,string body){string name=Name(suffix);if(Exists(c,name))throw new InvalidOperationException("name_collision");Owned.Add((kind,name));string sql=$"CREATE {kind} \"{name}\" {body}";try{Exec(c,sql);Results.Add(new{created=name,sql});}catch(Exception e){Results.Add(new{create_failed=name,sql,error=Error(e)});throw;}}
    static bool Exists(DmConnection c,string name)=>Convert.ToInt32(Scalar(c,$"SELECT COUNT(*) FROM USER_OBJECTS WHERE OBJECT_NAME='{name}'"))!=0;
    static object? Scalar(DmConnection c,string sql){using var cmd=c.CreateCommand();cmd.CommandText=sql;cmd.CommandTimeout=15;return cmd.ExecuteScalar();}
    static void Exec(DmConnection c,string sql){using var cmd=c.CreateCommand();cmd.CommandText=sql;cmd.CommandTimeout=15;cmd.ExecuteNonQuery();}
    static DmCommand Proc(DmConnection c,string suffix){var cmd=(DmCommand)c.CreateCommand();cmd.CommandType=CommandType.StoredProcedure;cmd.CommandText=Name(suffix);cmd.CommandTimeout=15;return cmd;}
    static DmParameter P(string name,DmDbType type,ParameterDirection direction,object value)=>new(name,type){Direction=direction,Value=value};
    static void Case(string name,Func<DmConnection,object> run){try{using var c=Open();Results.Add(new{name,result=run(c)});}catch(Exception e){Results.Add(new{name,error=Error(e)});}}
    static object Error(Exception e){if(e is TargetInvocationException{InnerException:{} inner})e=inner;return new{type=e.GetType().FullName,code=e.GetType().GetProperty("Number",Flags)?.GetValue(e),hresult=e.HResult};}
    static object Values(DmCommand cmd)=>cmd.Parameters.Cast<DmParameter>().Select(p=>new{name=p.ParameterName,direction=p.Direction.ToString(),type=p.Value?.GetType().FullName,value=SafeValue(p.Value)}).ToArray();
    static object? SafeValue(object? value)=>value switch{null=>null,DBNull=>"DBNULL",byte[] b=>Convert.ToHexString(b),DateTime d=>d.ToString("O"),DateTimeOffset d=>d.ToString("O"),decimal d=>d.ToString(System.Globalization.CultureInfo.InvariantCulture),string or int or long or short or double or float or bool=>value,DmIntervalDT or DmIntervalYM=>value.ToString(),_=>"<opaque>"};
    static List<object> ReadAll(DbDataReader r){var result=new List<object>();do{var rows=new List<object>();while(r.Read())rows.Add(Enumerable.Range(0,r.FieldCount).Select(i=>SafeValue(r.GetValue(i))).ToArray());result.Add(new{fields=r.FieldCount,rows});}while(r.NextResult());return result;}
    static object? Statement(DmCommand cmd)=>cmd.GetType().GetField("m_Stmt",Flags)?.GetValue(cmd);
    static object? StatementSql(DmCommand cmd){var s=Statement(cmd);return s?.GetType().GetFields(Flags).Where(f=>f.FieldType==typeof(string)).Select(f=>f.GetValue(s) as string).ToArray();}
    static DbDataReader IndependentReader(DmParameter parameter){var st=parameter.GetType().GetField("m_refCursorStmt",Flags)!.GetValue(parameter)!;var fields=st.GetType().GetFields(Flags);var cache=fields.Single(f=>f.FieldType.Name=="DmResultSetCache").GetValue(st);var info=fields.First(f=>f.FieldType.Name=="DmInfo").GetValue(st);var ctor=typeof(DmDataReader).GetConstructors(Flags).Single(x=>x.GetParameters().Length==3&&x.GetParameters()[0].ParameterType.Name=="DmResultSetCache");return (DbDataReader)ctor.Invoke(new[]{cache,info,(object)CommandBehavior.Default});}
    static object ConnectionMetadata(DmConnection c){var props=c.GetType().GetProperty("ConnProperty",Flags)?.GetValue(c);return props?.GetType().GetFields(Flags).Where(f=>f.Name=="msgVersion").Select(f=>f.GetValue(props)).ToArray()??[];}
    static object Wire(object statement){return statement.GetType().GetFields(Flags).Where(f=>f.FieldType.Name=="b").Select(f=>{var buf=f.GetValue(statement)!;var bytes=(byte[])buf.GetType().GetFields(Flags).Single(f=>f.FieldType==typeof(byte[])).GetValue(buf)!;int length=BitConverter.ToInt32(bytes,6);short opcode=BitConverter.ToInt16(bytes,4);bool allowed=opcode is 6 or 13 or 187;return new{opcode,length,body=allowed&&length>=0&&length<=1024?Convert.ToHexString(bytes,64,length):"not_captured",cursor_positions=buf.GetType().GetFields(Flags).Where(f=>f.FieldType==typeof(int)).Select(f=>f.GetValue(buf)).ToArray()};}).ToArray();}
    static object CursorMetadata(DmCommand cmd){var s=Statement(cmd);var info=s?.GetType().GetMethod("H",Flags,null,Type.EmptyTypes,null)?.Invoke(s,null);var values=info?.GetType().GetMethod("GetParamsInfo",Flags,null,Type.EmptyTypes,null)?.Invoke(info,null) as Array;return cmd.Parameters.Cast<DmParameter>().Where(p=>p.DmSqlType==DmDbType.RefCursor).Select((p,i)=>{var st=p.GetType().GetField("m_refCursorStmt",Flags)?.GetValue(p);object? id=null;try{id=st?.GetType().GetMethod("g",Flags,null,Type.EmptyTypes,null)?.Invoke(st,null);}catch{}object? bound=null;try{var v=values?.GetValue(i) ?? p.Value;var bytes=v.GetType().GetMethod("GetInValue",Flags,null,new[]{typeof(int)},null)?.Invoke(v,new object[]{0}) as byte[];bound=bytes==null?null:new{length=bytes.Length,hex=Convert.ToHexString(bytes)};}catch{}return new{name=p.ParameterName,statement_type=st?.GetType().FullName,id,bound,fields=st?.GetType().GetFields(Flags).Select(f=>new{name=f.Name,type=f.FieldType.Name}).ToArray(),reader_constructors=typeof(DmDataReader).GetConstructors(Flags).Select(c=>c.GetParameters().Select(p=>p.ParameterType.Name).ToArray()).ToArray()};}).ToArray();}
    static object Metadata(DmCommand cmd){var s=Statement(cmd);var info=s?.GetType().GetMethod("H",Flags,null,Type.EmptyTypes,null)?.Invoke(s,null);var values=info?.GetType().GetMethod("GetParamsInfo",Flags,null,Type.EmptyTypes,null)?.Invoke(info,null);if(values is not Array ps)return new{available=false};return ps.Cast<object>().Select(p=>new{fields=p.GetType().GetFields(Flags).Where(f=>f.FieldType.IsPrimitive||f.FieldType.IsEnum).ToDictionary(f=>f.Name,f=>f.GetValue(p)),methods=p.GetType().GetMethods(Flags).Where(m=>m.GetParameters().Length==0&&new[]{"GetName","GetCType","GetSqlType","GetScale","GetPrecision","GetIoType","GetTypeFlag","GetIOType","GetDirection","GetCursorStmtId","GetParameterMode","GetInOutType"}.Contains(m.Name)).ToDictionary(m=>m.Name,m=>m.Invoke(p,null))}).ToArray();}
}

